def transform(grid):
    h,w=len(grid),len(grid[0])
    for name,key in (('diff',lambda i,j:(j-i)),('sum',lambda i,j:(i+j))):
        for p in range(1,w+1):
            P={}; ok=True
            for i in range(h):
                for j in range(w):
                    if grid[i][j]:
                        k=key(i,j)%p
                        if k in P and P[k]!=grid[i][j]: ok=False; break
